// Generates server/agent-onboarding-content.ts from the agent-facing source
// documents. The generated file is checked in; re-run
// `node scripts/gen-agent-onboarding.mjs` after editing the sources, or pass
// `--check` to verify the committed copy is in sync (tests do this).

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const out = join(root, "server/agent-onboarding-content.ts");

// Normalize line endings: a Windows checkout with core.autocrlf hands back CRLF,
// which would embed \r\n in the generated file and make --check fail on a tree
// that is in fact in sync.
const read = (p) => readFileSync(join(root, p), "utf8").replace(/\r\n/g, "\n");
const stripFrontmatter = (md) => md.replace(/^---\n[\s\S]*?\n---\n+/, "");

const skillBody = stripFrontmatter(read("skills/heinote/SKILL.md")).trim();
const helper = read("skills/heinote/heinote").replace(/\n+$/, "");
const agentApi = read("docs/agent-api.md").trim();

const FENCE = "```";

// The served skill is a single self-contained document: the SKILL.md guide,
// then the embeddable helper script, then a pointer to the live contract. An
// agent that can fetch one URL can self-install. Build by concatenation so the
// markdown fences never fight the JS template literal.
const skillMd = [
  skillBody,
  "",
  "## 下载与安装",
  "",
  "本文件即接入技能本体，由部署站点在 `GET /api/v1/skill.md` 公开托管。",
  "把下方 `python` 代码块存为可执行文件，即得到 `heinote` 命令行脚本",
  "（Python 3，零依赖）：",
  "",
  FENCE + "sh",
  'curl -s "$SITE/api/v1/skill.md" -o heinote-skill.md',
  "# 解出脚本：取 ```python 与下一个 ``` 之间的内容",
  "awk '/^" + FENCE + "python$/{f=1;next} /^" + FENCE + "$/{f=0} f' heinote-skill.md > heinote",
  "chmod +x heinote",
  FENCE,
  "",
  "完整接口契约另见同站 `GET /api/v1/agent-api.md`（与本文件同源，免鉴权）。",
  "站点导览见 `GET /llms.txt`。",
  "",
  "## 内嵌 heinote 脚本",
  "",
  FENCE + "python",
  helper,
  FENCE,
  "",
].join("\n");

const llmsTxt = [
  "# 小黑笔记 (HeiNote)",
  "",
  "> 自托管笔记应用：文档页面、Database、附件与实时共编。Agent 可通过 HTTP",
  "> REST API 完整读写页面与数据库、上传附件、提交可审核修改提案。",
  "",
  "## Agent 接入",
  "",
  "- [站点根路径](/): `GET /` 且 `Accept` 不含 `text/html` 时返回本导览——把裸站点 URL 交给 Agent 即可自举",
  "- [接入技能](api/v1/skill.md): 使用说明 + 内嵌 heinote 命令行助手脚本，一次抓取即完成接入",
  "- [API 契约](api/v1/agent-api.md): 完整接口文档（认证、页面、数据库、附件、提案、版本）",
  "- [版本探测](api/version): 部署名称与版本号",
  "",
  "## 授权（免手动令牌自举）",
  "",
  "Agent 无需预置凭据，四步拿到 Bearer 令牌：",
  "",
  "1. `POST /api/v1/auth/requests`，body `{\"name\":\"<自称>\",\"access\":\"read|write\"}`",
  "   → 201 返回 `id`、`verificationUrl`、`expiresAt`（请求 10 分钟过期）。",
  "2. 让已登录用户打开 `verificationUrl` 并在授权页批准（本机可直接 `open` 该 URL；",
  "   此链接即批准凭据，勿转发）。",
  "3. 轮询 `GET /api/v1/auth/requests/:id`，`status` 变 `approved` 时首个响应附带",
  "   `token`（`notes_` 前缀，仅出现一次，立即保存）。`denied`/`expired` 即未获授权。",
  "4. 之后所有请求带 `Authorization: Bearer <token>` 调 `/api/v1/*`；",
  "   `read` 令牌只可 GET 与 `POST /databases/:id/query`。",
  "",
  "```sh",
  'curl -s -X POST "$SITE/api/v1/auth/requests" \\',
  '  -H "Content-Type: application/json" \\',
  '  -d \'{"name":"my-agent","access":"write"}\'',
  "```",
  "",
].join("\n");

// Serialize as JSON strings so the emitted module never needs escaping care.
const emit = `// Generated by scripts/gen-agent-onboarding.mjs. Do not edit by hand.
// Sources: skills/heinote/SKILL.md, skills/heinote/heinote, docs/agent-api.md,
// and the llms.txt template in the generator. Re-run the script after changes.

export const llmsTxt = ${JSON.stringify(llmsTxt)};

export const skillMd = ${JSON.stringify(skillMd)};

export const agentApiMd = ${JSON.stringify(agentApi)};
`;

if (process.argv.includes("--check")) {
  if (read("server/agent-onboarding-content.ts") !== emit) {
    console.error("server/agent-onboarding-content.ts is out of date; run `node scripts/gen-agent-onboarding.mjs`.");
    process.exit(1);
  }
  console.log("agent-onboarding-content.ts is in sync.");
} else {
  writeFileSync(out, emit);
  console.log(`wrote ${out}`);
}
